// spec: specs/orders.md §21 · кейс .qa/tests/orders/ord-36-mobile-cards-actions-pagination.md
// seed: tests/seed.admin.spec.ts
// #4f5292 (עבר QA 26.10): на телефоне (360/375/390) «⋮» каждой строки и пагинация видны без горизонтальной прокрутки;
// строки — карточки (номер · клиент · ⋮ / дата · פריטים · סכום / статусы), номер/клиент/дата не обрезаны, клик по карточке открывает заказ.
// Регресс 1024 (с сайдбаром — тоже карточки) и 1440 (таблица, Figma 6:2).
// Только чтение: пагинация, меню «⋮», открытие заказа. Ничего не утверждается/не отклоняется.
// Положение кнопок проверяется ДО любой прокрутки вбок (Playwright при клике сам прокручивает контейнеры — это скрыло бы баг).
import { test, expect, Page, Locator } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const PER_PAGE = 8;
const cards = (page: Page) => page.getByRole('button', { name: /^#\d+ / });
const actions = (card: Locator) => card.getByRole('button', { name: /פעולות|⋮/ });
const shown = (page: Page) => page.getByText(/^מציג \d+–\d+ מתוך \d+ תוצאות$/);

async function openOrdersAll(page: Page) {
  await page.goto('/orders');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  await expect(cards(page).first()).toBeVisible({ timeout: 30_000 });
  await expect(shown(page)).toHaveText(/^מציג 1–8 מתוך \d+ תוצאות$/, { timeout: 20_000 });
}

const total = async (page: Page) => Number((await shown(page).innerText()).match(/מתוך (\d+)/)![1]);

/** Нет горизонтальной прокрутки у страницы и у предков первой карточки (контейнер списка). */
async function expectNoHorizontalScroll(page: Page) {
  expect(await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth)).toBeLessThanOrEqual(1);
  const scrollers = await cards(page).first().evaluate((el) => {
    const bad: string[] = [];
    for (let p = el.parentElement; p && p !== document.body; p = p.parentElement) {
      const ox = getComputedStyle(p).overflowX;
      if ((ox === 'auto' || ox === 'scroll') && p.scrollWidth - p.clientWidth > 1) bad.push(`${p.tagName}.${p.className} ${p.scrollWidth}>${p.clientWidth}`);
    }
    return bad;
  });
  expect(scrollers, 'контейнер списка прокручивается вбок').toEqual([]);
}

/** Горизонтально целиком в экране (вертикаль не важна). */
async function expectInViewX(page: Page, l: Locator, what: string) {
  await expect(l, what).toBeVisible();
  const b = (await l.boundingBox())!;
  const vw = page.viewportSize()!.width;
  expect(b.x, `${what}: левый край`).toBeGreaterThanOrEqual(-1);
  expect(b.x + b.width, `${what}: правый край`).toBeLessThanOrEqual(vw + 1);
}

/** «⋮» каждой карточки страницы в экране; номер/дата не обрезаны; номер и тексты карточки не уходят за экран. */
async function expectCardsFit(page: Page) {
  const n = await cards(page).count();
  expect(n).toBeGreaterThan(0);
  expect(n).toBeLessThanOrEqual(PER_PAGE);
  for (let i = 0; i < n; i++) {
    const card = cards(page).nth(i);
    await expectInViewX(page, actions(card), `«⋮» карточки ${i + 1}`);
    const leaves = await card.evaluate((el) => {
      const vw = window.innerWidth;
      return [...el.querySelectorAll('*')]
        .filter((k) => k.children.length === 0 && (k.textContent || '').trim() && (k as HTMLElement).offsetParent !== null)
        .map((k) => {
          const r = k.getBoundingClientRect();
          if (r.width <= 2 || r.height <= 2) return { t: '', cut: false, out: false }; // sr-only подписи
          return { t: (k.textContent || '').trim(), cut: k.scrollWidth - k.clientWidth > 1 && k.clientWidth > 0, out: r.left < -1 || r.right > vw + 1 };
        })
        .filter((x) => x.cut || x.out);
    });
    expect(leaves, `карточка ${i + 1}: обрезанные/за экраном тексты`).toEqual([]);
    await expect(card.getByText(/^#\d+$/)).toBeVisible();
    await expect(card.getByText(/\d{2}\.\d{2}\.\d{4}/).first()).toBeVisible();
  }
}

/** Пагинация целиком в экране после вертикальной прокрутки вниз (без прокрутки вбок). */
async function expectPaginationInView(page: Page) {
  await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
  for (const name of ['העמוד הקודם', 'העמוד הבא']) await expectInViewX(page, page.getByRole('button', { name }), `«${name}»`);
  await expectInViewX(page, page.getByRole('button', { name: '1', exact: true }), 'номер страницы «1»');
  // RTL: «העמוד הקודם» справа, «העמוד הבא» слева (как на 1440)
  const prev = (await page.getByRole('button', { name: 'העמוד הקודם' }).boundingBox())!;
  const next = (await page.getByRole('button', { name: 'העמוד הבא' }).boundingBox())!;
  expect(prev.x).toBeGreaterThan(next.x);
}

test.describe('orders — «הזמנות» בטלפון: כרטיסים, «⋮» ועימוד בתוך המסך (#4f5292)', () => {
  for (const width of [360, 375, 390]) {
    test(`${width}: אין גלילה לרוחב; «⋮» של כל כרטיס והעימוד בתוך המסך; מספר/לקוח/תאריך לא חתוכים #4f5292 @iphone @prod-safe`, async ({ page }) => {
      await page.setViewportSize({ width, height: 664 });
      await openOrdersAll(page);
      await expectNoHorizontalScroll(page);
      await expectCardsFit(page);
      // карточка: дата во второй строке, под номером (коммент программиста 99228ff)
      const card = cards(page).first();
      const num = (await card.getByText(/^#\d+$/).boundingBox())!;
      const date = (await card.getByText(/\d{2}\.\d{2}\.\d{4}/).first().boundingBox())!;
      expect(date.y).toBeGreaterThanOrEqual(num.y + num.height - 1);
      await expectPaginationInView(page);
    });
  }

  test('390: «⋮» של הכרטיס האחרון פותח את תפריט הפעולות (לא את ההזמנה) #4f5292 @iphone @prod-safe', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 664 });
    await openOrdersAll(page);
    const last = cards(page).last();
    await expectInViewX(page, actions(last), '«⋮» последней карточки');
    await actions(last).click();
    await expect(page.getByRole('menuitem', { name: 'פרטי הזמנה' }).or(page.getByText('פרטי הזמנה', { exact: true })).first()).toBeVisible({ timeout: 10_000 });
    await expect(page).toHaveURL(/\/orders\/?(\?.*)?$/);
    await page.keyboard.press('Escape');
  });

  test('390: עימוד — «העמוד הבא» / «העמוד הקודם» / העמוד האחרון #4f5292 @iphone @prod-safe', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 664 });
    await openOrdersAll(page);
    const n = await total(page);
    test.skip(n <= PER_PAGE, `всего ${n} заказов — одна страница`);
    await expectPaginationInView(page);
    await page.getByRole('button', { name: 'העמוד הבא' }).click();
    await expect(shown(page)).toHaveText(new RegExp(`^מציג 9–\\d+ מתוך ${n} תוצאות$`));
    await expectNoHorizontalScroll(page);
    await expectCardsFit(page);
    await expectPaginationInView(page);
    await page.getByRole('button', { name: 'העמוד הקודם' }).click();
    await expect(shown(page)).toHaveText(`מציג 1–8 מתוך ${n} תוצאות`);
    const pages = Math.ceil(n / PER_PAGE);
    await expectPaginationInView(page);
    const lastBtn = page.getByRole('button', { name: String(pages), exact: true });
    await expectInViewX(page, lastBtn, `номер последней страницы «${pages}»`);
    await lastBtn.click();
    await expect(shown(page)).toHaveText(`מציג ${(pages - 1) * PER_PAGE + 1}–${n} מתוך ${n} תוצאות`);
    await expect(page.getByRole('button', { name: 'העמוד הבא' })).toBeDisabled();
    await expectCardsFit(page);
  });

  test('390: לחיצה על הכרטיס פותחת את ההזמנה #4f5292 @iphone @prod-safe', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 664 });
    await openOrdersAll(page);
    const num = cards(page).first().getByText(/^#\d+$/);
    const no = (await num.innerText()).replace('#', '');
    await num.click();
    await expect(page).toHaveURL(/\/orders\/[0-9a-f-]{36}$/, { timeout: 30_000 });
    await expect(page.getByRole('heading', { level: 1, name: new RegExp(`^הזמנה #${no}`) })).toBeVisible({ timeout: 30_000 });
  });

  test('רגרסיה 1024 (סרגל צד פתוח): אין גלילה לרוחב, «⋮» והעימוד בתוך המסך #4f5292 @desktop @prod-safe', async ({ page }) => {
    await page.setViewportSize({ width: 1024, height: 768 });
    await openOrdersAll(page);
    await expectNoHorizontalScroll(page);
    await expectCardsFit(page);
    await expectPaginationInView(page);
  });

  test('רגרסיה 1440: טבלה — מספר ותאריך באותה שורה, «⋮» והעימוד בתוך המסך #4f5292 @desktop @prod-safe', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await openOrdersAll(page);
    await expectNoHorizontalScroll(page);
    const row = cards(page).first();
    const num = (await row.getByText(/^#\d+$/).boundingBox())!;
    const date = (await row.getByText(/\d{2}\.\d{2}\.\d{4}/).first().boundingBox())!;
    expect(Math.abs(date.y + date.height / 2 - (num.y + num.height / 2))).toBeLessThanOrEqual(4);
    await expectCardsFit(page);
    await expectPaginationInView(page);
  });
});
